import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.ChTAMbUy.js";const n="/docs/assets/automatic-tool-calling.CsrzMKAq.png",p=JSON.parse('{"title":"LLM Serving","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentops/llm_serving.md","filePath":"versions/development/agentops/llm_serving.md","lastUpdated":1787837970000}'),s={name:"development/agentops/llm_serving.md"};function l(i,e,d,g,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="llm-serving" tabindex="-1">LLM Serving <a class="header-anchor" href="#llm-serving" aria-label="Permalink to &quot;LLM Serving&quot;">​</a></h1><p>LLM Serving deploys self-hosted models as OpenAI-compatible inference endpoints on KServe. It supports text generation, embedding, reranking, text-to-speech, and speech-to-text models. Use it when you want to host a model in the cluster instead of calling an external provider such as OpenAI, Anthropic, or Gemini.</p><div class="info custom-block"><p class="custom-block-title">Upstream references</p><p>LLM Serving builds on:</p><ul><li><a href="https://kserve.github.io/website/" target="_blank" rel="noreferrer">KServe</a> for the serving control plane and OpenAI-compatible protocol</li><li><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM</a> and <a href="https://kserve.github.io/website/latest/modelserving/v1beta1/llm/huggingface/" target="_blank" rel="noreferrer">KServe&#39;s HuggingFace runtime</a> for text generation and embeddings</li><li><a href="https://huggingface.co/docs/text-embeddings-inference" target="_blank" rel="noreferrer">Hugging Face Text Embeddings Inference (TEI)</a> for CPU-optimized embeddings</li><li><a href="https://github.com/SYSTRAN/faster-whisper" target="_blank" rel="noreferrer">faster-whisper</a> for CPU speech-to-text</li></ul></div><p>LLM Serving is an AgentOps capability. For classic model serving with scikit-learn, PyTorch, and similar predictors, see <a href="./../mlops/model_serving.html">Model Serving</a>. Both features use KServe, but they provide different deployment forms and endpoints.</p><h2 id="when-to-use-llm-serving" tabindex="-1">When to Use LLM Serving <a class="header-anchor" href="#when-to-use-llm-serving" aria-label="Permalink to &quot;When to Use LLM Serving&quot;">​</a></h2><ul><li>Host an open-weight model (Llama, Mistral, Qwen, Gemma, and similar) in-cluster instead of calling an external API.</li><li>Serve embedding or reranking models for retrieval workloads.</li><li>Serve text-to-speech or speech-to-text models.</li><li>Provide an in-cluster model for a kagent <a href="./agents.html">Agent</a> via an <strong>Internal</strong> Model Configuration, with or without tool calling.</li><li>Keep model traffic and data inside the cluster instead of sending it to an external provider.</li></ul><p>If you only need OpenAI, Anthropic, or Gemini, create a Model Configuration directly instead. See <a href="./agents.html#_2-choose-or-create-a-model-configuration">Agents: Choose or Create a Model Configuration</a>.</p><h2 id="deploy-a-model" tabindex="-1">Deploy a Model <a class="header-anchor" href="#deploy-a-model" aria-label="Permalink to &quot;Deploy a Model&quot;">​</a></h2><p>Open <strong>LLM Serving</strong> in the sidebar. The page lists deployed models for the selected workspace, filterable by type (<strong>All / Text Generation / Embedding / Reranking</strong>), with columns for name, status, model ID, type, runtime, and age.</p><p>Click <strong>Deploy Model</strong> and choose a preset, or select <strong>Deploy Custom Model</strong> to configure the deployment from scratch. Presets provide curated defaults and can be searched or filtered by GPU count, task type, and verification status. Both paths open the same form:</p><ul><li><strong>Deployment Name</strong>: unique name in the workspace.</li><li><strong>Model Type</strong>: Text Generation, Embedding, Reranking, Text to Speech, or Speech to Text. Typing a HuggingFace-style model ID (<code>org/model</code>) auto-detects the type.</li><li><strong>Model ID</strong>: a HuggingFace model ID, for example <code>meta-llama/Llama-2-7b-chat-hf</code>. HuggingFace is the only model source available in the form; use the YAML editor for other storage URIs.</li><li><strong>Runtime</strong>: filtered to runtimes that support the selected type. Options include HuggingFace (recommended for text generation and embeddings), TEI (CPU-optimized embeddings), vLLM, vLLM Omni (audio models), and faster-whisper (CPU speech-to-text). vLLM requires a custom ClusterServingRuntime.</li></ul><p>If the model is gated on HuggingFace, the form warns you before deploying: accept the license on huggingface.co, create an access token, and store it as a Kubernetes Secret named <code>storage-config</code> with key <code>HF_TOKEN</code> in the workspace (see <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a>). Deployment fails without it.</p><p>Select <strong>Or edit YAML manifest directly</strong> if the form does not cover a setting you need, such as a custom storage URI or extra container arguments.</p><h2 id="advanced-configuration" tabindex="-1">Advanced Configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced Configuration&quot;">​</a></h2><p>The <strong>Advanced Configuration</strong> section is collapsed by default. It covers:</p><ul><li><a href="https://kserve.github.io/website/docs/concepts/architecture/control-plane" target="_blank" rel="noreferrer"><strong>Deployment Mode</strong></a>: <strong>Serverless (Knative)</strong> is the default and supports scale-to-zero. <strong>Raw (also called Standard in newer KServe versions) Deployment</strong> creates a plain Kubernetes Deployment for clusters without Knative or for <a href="https://keda.sh/docs/latest/concepts/scaling-deployments/" target="_blank" rel="noreferrer">KEDA</a> autoscaling. Raw deployments require at least one replica.</li><li><strong>Runtime settings</strong>: vLLM-based runtimes support quantization options such as AWQ, GPTQ, and FP8, and data types such as Float16, BFloat16, and Float32. The HuggingFace runtime uses vLLM internally, so these settings also apply to it.</li><li><strong>Resource Requests</strong>: configure CPU, memory, and GPU count and type. GPU options come from the cluster inventory. If limits are left blank, the CPU limit defaults to twice the request and the memory limit matches the request.</li><li><strong>Auto-Scaling</strong>: configure minimum and maximum replicas, with a maximum of 10. Serverless mode allows a minimum of 0 for scale-to-zero; Raw Deployment requires at least one replica.</li><li><strong>Automatic tool calling</strong>: configure support for agents that use MCP tools. See <a href="#enable-tool-calling-for-agents">Enable Tool Calling for Agents</a>.</li></ul><p>Raw deployments can use <a href="https://kubernetes.io/docs/tasks/run-application/horizontal-pod-autoscale/" target="_blank" rel="noreferrer">HPA</a> for CPU or memory-based scaling, or <a href="https://keda.sh/docs/latest/concepts/scaling-deployments/" target="_blank" rel="noreferrer">KEDA</a> for custom Prometheus metrics such as vLLM token throughput. KEDA requires a PromQL query and a scale threshold calibrated against observed traffic. See <a href="./../mlops/model_serving_autoscaling.html">Serving Autoscaling</a> for the general KEDA pattern in prokube.</p><h2 id="enable-tool-calling-for-agents" tabindex="-1">Enable Tool Calling for Agents <a class="header-anchor" href="#enable-tool-calling-for-agents" aria-label="Permalink to &quot;Enable Tool Calling for Agents&quot;">​</a></h2><p>Not every runtime supports OpenAI-style tool calling. The <strong>Enable automatic tool calling</strong> option appears only for <strong>vLLM</strong> and <strong>HuggingFace</strong> text-generation models. It is not available for TEI, vLLM Omni, faster-whisper, or other model types.</p><p>If you plan to attach MCP tools to a kagent agent that uses this model (an <strong>Internal</strong> Model Configuration), turn this on and select a <strong>Tool-call parser</strong> matching the model&#39;s tool-call format:</p><table tabindex="0"><thead><tr><th>Parser</th><th>Matches</th></tr></thead><tbody><tr><td>Hermes</td><td>Qwen 2.5, QwQ, and Nous Hermes formats</td></tr><tr><td>Qwen3 XML</td><td>Qwen3-Coder tool-call format</td></tr><tr><td>Llama 3 JSON</td><td>Llama models using JSON tool calls</td></tr><tr><td>Pythonic</td><td>Llama models using Python-style tool calls</td></tr><tr><td>Mistral</td><td>Mistral tool-call format</td></tr><tr><td>DeepSeek V3</td><td>DeepSeek V3 format</td></tr><tr><td>DeepSeek V3.1</td><td>DeepSeek V3.1 format</td></tr></tbody></table><p><img src="'+n+'" alt="LLM deployment form with automatic tool calling and parser selection" loading="lazy"></p><p>This list matches the parsers built into the platform&#39;s currently deployed vLLM runtime and may change as that runtime is upgraded; use YAML editing for a parser or chat template not listed here. Without a matching parser, an agent&#39;s tool calls against this model will not work reliably even though the Model Configuration and deployment are otherwise valid.</p><h2 id="test-a-deployed-model" tabindex="-1">Test a Deployed Model <a class="header-anchor" href="#test-a-deployed-model" aria-label="Permalink to &quot;Test a Deployed Model&quot;">​</a></h2><p>Open a <strong>Ready</strong> model from the list. Text-generation models have a <strong>Chat</strong> tab with a built-in streaming chat tester. Embedding and reranking models have an <strong>API</strong> tab. Audio models have an <strong>API</strong> or <strong>Test</strong> tab, depending on the task. These tabs show the endpoint path and a ready-to-run <code>curl</code> example for the supported operation.</p><p>The Configuration tab also shows Basic Information, Resources, Scaling, and API Endpoints for the model, alongside Metrics, Logs, and Conditions tabs for troubleshooting. While model weights are downloading, a storage panel shows progress (queued, preparing, downloading, or failed) instead of the usual tabs.</p><h2 id="edit-a-model" tabindex="-1">Edit a Model <a class="header-anchor" href="#edit-a-model" aria-label="Permalink to &quot;Edit a Model&quot;">​</a></h2><p>From the model list or detail page, select <strong>Edit</strong> to change Model Type, Quantization, Data Type, tool-calling settings, resource requests and limits, or auto-scaling. Model ID, runtime, and deployment mode are fixed after creation. To change them, delete and redeploy the model or use the <strong>YAML</strong> tab.</p><h2 id="external-access" tabindex="-1">External Access <a class="header-anchor" href="#external-access" aria-label="Permalink to &quot;External Access&quot;">​</a></h2><p>Endpoints shown on the model&#39;s detail/API tabs are the workspace-internal serving URL, useful for testing from inside the platform. For external clients (SDKs, CI jobs, applications outside the cluster), call the model through <a href="./../platform/agent_gateway.html">Agent Gateway</a> instead, using a URL of the form <code>/ai/&lt;workspace&gt;/models/&lt;route-id&gt;/v1/...</code> and an API key scoped to the model. See <a href="./../platform/api_keys.html">API Keys</a>. Models granted through <a href="./../admin/external_models.html">External Models</a> are reachable through this same URL pattern.</p><p>To use a deployed model from a kagent agent instead of an external client, create an <strong>Internal - OpenAI-compatible</strong> Model Configuration and pick this model from the <strong>LLM Serving model</strong> dropdown. See <a href="./agents.html#_2-choose-or-create-a-model-configuration">Agents</a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./agents.html">Agents</a></li><li><a href="./agent_gateway.html">Agent Gateway</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/model_serving_autoscaling.html">Serving Autoscaling</a></li></ul>',33)])])}const u=t(s,[["render",l]]);export{p as __pageData,u as default};
